// HasAssignment applies the HasEdge predicate on the "assignment" edge.
func HasAssignment() predicate.DeliveryWindow {
	return predicate.DeliveryWindow(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, AssignmentTable, AssignmentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasAssignmentWith applies the HasEdge predicate on the "assignment" edge with a given conditions (other predicates).
func HasAssignmentWith(preds ...predicate.OrderAssignment) predicate.DeliveryWindow {
	return predicate.DeliveryWindow(func(s *sql.Selector) {
		step := newAssignmentStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.DeliveryWindow) predicate.DeliveryWindow {
	return predicate.DeliveryWindow(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.DeliveryWindow) predicate.DeliveryWindow {
	return predicate.DeliveryWindow(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.DeliveryWindow) predicate.DeliveryWindow {
	return predicate.DeliveryWindow(sql.NotPredicates(p))
}
